mapper.select:
select zydh as dm, zymc as dmmc
from t_zydm, td_zdb
where t_zydm.yxdm = td_zdb.dm
        and td_zdb.dmlb = 'yxdm'
        and td_zdb.dmmc = #{yx}
        and year = #{year}

select td_zdb.dmmc
from t_zydm, td_zdb
where t_zydm.yxdm = td_zdb.dm
  and td_zdb.dmlb = 'yxdm'
  and t_zydm.zydh = #{zydh}
  and year = #{year}

select zydh
from t_zydm
where zymc = #{zymc}
      and year = #{year}
